with incoming as (select value from jsonb_array_elements('[{"id":"mr30","title":"มร.30 ภาค 2/2569","detail":"มหาวิทยาลัยรามคำแหง: ม.ร.30 ภาค 2/2569 หน้า 142–143; ตรวจฉบับแก้ไขกับมหาวิทยาลัย","url":"https://www.regis.ru.ac.th/document/6_regis_examSV/MorLor30/20260904_mr30_269.pdf","backupUrl":"./sources/mr30-2-2569-p142-143.pdf","listingUrl":"https://www.regis.ru.ac.th/index.php/schedule/mr30_central","accessNote":"หากต้นฉบับเปิดไม่ได้ ใช้สำเนาหน้า 142–143 ด้านล่างได้ทันที และตรวจฉบับแก้ไขกับมหาวิทยาลัยก่อนเรียนหรือสอบ"},{"id":"video","title":"RU Course on Demand","detail":"ดูคำบรรยายย้อนหลัง ใช้บัญชี RU e-Service เลือกส่วนกลางและภาค 2/2569 เมื่อมีเผยแพร่ ไม่ใช่ช่องทางดูสด; ณ 14 ต.ค. หน้าเว็บแสดงภาค 1/2569","url":"https://ondemand.ru.ac.th/","accessNote":"ตรวจจากเครือข่ายทดสอบ 14 ต.ค. 2569 เปิดปลายทางไม่สำเร็จหรือหมดเวลารอ ไม่ถือเป็นหลักฐานว่าเว็บหยุดให้บริการทุกเครือข่าย"},{"id":"faculty","title":"คณะรัฐศาสตร์ มหาวิทยาลัยรามคำแหง","detail":"ประกาศผู้สอน เอกสารประกอบการเรียน และเงื่อนไขประจำภาค","url":"https://www.pol.ru.ac.th/","accessNote":"ตรวจจากเครือข่ายทดสอบ 14 ต.ค. 2569 เปิดปลายทางไม่สำเร็จหรือหมดเวลารอ ไม่ถือเป็นหลักฐานว่าเว็บหยุดให้บริการทุกเครือข่าย"},{"id":"regis","title":"สำนักบริการทางวิชาการและทดสอบประเมินผล","detail":"ทะเบียนและปฏิทินการศึกษา","url":"https://www.regis.ru.ac.th/","accessNote":"ตรวจจากเครือข่ายทดสอบ 14 ต.ค. 2569 เปิดปลายทางไม่สำเร็จหรือหมดเวลารอ ไม่ถือเป็นหลักฐานว่าเว็บหยุดให้บริการทุกเครือข่าย"},{"id":"bookstore","title":"ร้านหนังสือมหาวิทยาลัยรามคำแหง","detail":"ร้านหนังสือมหาวิทยาลัย ใช้รหัสวิชาค้นตำรา ตรวจฉบับกับผู้สอนก่อนซื้อ; เปลี่ยนลิงก์สินค้าระบบเก่ามายังหน้าร้านปัจจุบัน","url":"https://bookstore.ru.ac.th/","accessNote":"ตรวจจากเครือข่ายทดสอบ 14 ต.ค. 2569 เปิดปลายทางไม่สำเร็จหรือหมดเวลารอ ไม่ถือเป็นหลักฐานว่าเว็บหยุดให้บริการทุกเครือข่าย"},{"id":"live","title":"RU Cyber Classroom — เรียนสด","detail":"ช่องทางถ่ายทอดสดตามตาราง ม.ร.30 เลือกส่วนกลางและห้องเรียนของวิชา ตรวจว่ามีถ่ายทอดในวันนั้น","url":"https://cyberclassroom.ru.ac.th/","listingUrl":"https://www.ru.ac.th/th/study_online","accessNote":"ตรวจจากเครือข่ายทดสอบ 14 ต.ค. 2569 เปิดปลายทางไม่สำเร็จหรือหมดเวลารอ ไม่ถือเป็นหลักฐานว่าเว็บหยุดให้บริการทุกเครือข่าย"},{"id":"video-announcement","title":"ประกาศเปลี่ยนระบบ RU Course on Demand","detail":"มหาวิทยาลัยประกาศ 17 ก.ค. 2569: ondemand.ru.ac.th เป็นวิดีโอคำบรรยายย้อนหลัง ตั้งแต่ 1/2569 เป็นต้นไป ใช้บัญชี RU e-Service; หน้าเว็บที่ตรวจ 14 ต.ค. ยังแสดงรายวิชา 1/2569 ไม่ยืนยันว่าคลิป 2/2569 พร้อมแล้ว","url":"https://ondemand.ru.ac.th/news/4bed6103-94f9-4635-9483-513e325c72cf/"},{"id":"cyber-rooms","title":"รายชื่อห้องที่ถ่ายทอดสดและบันทึกย้อนหลัง","detail":"ประกาศสาขาวิทยบริการฯ ตรัง 14 ก.ค. 2568 ระบุ KLB 501 และ VPB 501 ในรายชื่อห้อง Cyber Classroom; เป็นหลักฐานรองรับช่องทาง ไม่ยืนยันว่าคลิปภาค 2/2569 ถูกอัปโหลดแล้ว","url":"https://trang.ru.ac.th/index.php/component/content/article/ba14072568002?Itemid=101&catid=15%3Apr-ba"}]'::jsonb)), old as (select item,ord from public.ru_study_settings,jsonb_array_elements(value->'sources') with ordinality as x(item,ord) where key='config'), merged as (select coalesce((select value from incoming where value->>'id'=old.item->>'id'),old.item) as item,ord from old union all select value,1000+row_number() over () from incoming where not exists(select 1 from old where old.item->>'id'=incoming.value->>'id')) update public.ru_study_settings set value=jsonb_set(value,'{sources}',(select jsonb_agg(item order by ord) from merged)) where key='config';
